		public enum ESmoothType {			/// <summary> The handles are invisible (no smoothing) </summary>			CORNER,			/// <summary> The handles are moving independent (custom smooth) </summary>			BEZIER_CORNER,			/// <summary> The handles move together aligned in line (custom smooth) </summary>			BEZIER,			/// <summary> The handles are invisible (autosmooth) </summary>			SMOOTH		}		private void OnDotDoubleClick(object sender, EventArgs e) {			// Circle smooth types			var names = Enum.GetValues(typeof(ESmoothType))				.Cast<ESmoothType>()				.Select(v => v.ToString())				.ToArray();			var currentIndex = Array.IndexOf(names, SmoothType.ToString());			var nextName = names.GetNext(currentIndex);			Console.WriteLine("SplinePoint > OnDoubleClick > SmoothType:{0} Index:{1} Next:{2}", SmoothType, currentIndex, nextName);			SetSmoothType((ESmoothType)Enum.Parse(typeof(ESmoothType), nextName));		}